;==============================================================================
; _kUfsImp / _kUfsBank -- the callee module's bank, and the
; entry points inside it.  GENERATED by tools/gen_mod_imports.py; edit the
; table there, not this file.
;
; POPULATED ONCE, AT mod_init, from the vtable the loader resolves.  Zero
; until then, which is why the module refuses to run any C when a resolve
; fails -- a shim reading a zero would pile-call bank 0 offset $FFFF and the
; machine would come apart a long way from the cause.
;==============================================================================
_kUfsBank       DS      2               ; the callee's bank, in the low byte
_kUfsImp        DS      UFSCORE_COUNT*2

;------------------------------------------------------------------------------
; ufs_mountfs(devvp, mp, ump) -> errno.  12 argument bytes.
;------------------------------------------------------------------------------
ufs_mountfs     MX      %00
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     14,S
                PHA
                LDA     |_kUfsImp+UFSCORE_Mountfs
                                        ; MODBANK-OK: entered from C, which left
                                        ;   DBR on our bank -- and read HERE,
                                        ;   before the switch below, for exactly
                                        ;   that reason
                TAX                             ; X = target offset in the callee
                SEP     #$20
                MX      %10
                LDA     |_kUfsBank    ; MODBANK-OK: same, still before the
                                        ;   switch
                PHA                             ; one byte on...
                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; kufsret_ufs_mountfs is in OUR bank
                PEA     kufsret_ufs_mountfs-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
kufsret_ufs_mountfs TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #12
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL

;------------------------------------------------------------------------------
; ufs_fsyncvp(vp, fflags) -> errno.  6 argument bytes.
;
; fsync(2)'s last hop -- apple/fgx#355.  A one-line VOP_FSYNC dispatch, in
; ufs.mod because ufsdir.mod, where ufs_fsync lives, exports nothing by design.
;------------------------------------------------------------------------------
ufs_fsyncvp     MX      %00
                LDA     8,S
                PHA
                LDA     8,S
                PHA
                LDA     8,S
                PHA
                LDA     |_kUfsImp+UFSCORE_Fsync
                                        ; MODBANK-OK: entered from C, which left
                                        ;   DBR on our bank -- and read HERE,
                                        ;   before the switch below, for exactly
                                        ;   that reason
                TAX                             ; X = target offset in the callee
                SEP     #$20
                MX      %10
                LDA     |_kUfsBank    ; MODBANK-OK: same, still before the
                                        ;   switch
                PHA                             ; one byte on...
                PLB                             ; ...and straight off: DBR = the
                                                ;   callee.  NET ZERO, which is
                                                ;   why it can follow the copy.
                REP     #$30
                MX      %00
                PHK                             ; kufsret_ufs_fsyncvp is in OUR bank
                PEA     kufsret_ufs_fsyncvp-1
                PHB                             ; target bank: DBR is the callee's
                                                ;   now, and PHB is exactly the
                                                ;   one byte RTL wants
                TXA
                DEC     A
                PHA                             ; target - 1
                RTL                             ; PILECALL
kufsret_ufs_fsyncvp TAY                             ; park the return value; the stack
                                                ;   fix needs the register
                TSC
                CLC
                ADC     #6
                TCS
                TYA
                PHK
                PLB                             ; DBR ours again, recovered from
                                                ;   PB rather than saved
                RTL

